INSERT INTO `site_settings` VALUES (1,'social','{\"email\":\"itsamirzamani@gmail.com\",\"linkedin\":\"https:\\/\\/linkedin.com\\/in\\/amirhossein-zamanzade\",\"github\":\"https:\\/\\/github.com\\/Amir-dev00\",\"telegram\":\"https:\\/\\/t.me\\/Amir_dev00\",\"telegram_handle\":\"@Amir_dev00\"}','2026-11-09 10:46:57','2026-11-09 10:46:57'),(2,'profile','{\"name\":\"Amirhossein Zamanzade\",\"photo\":\"assets\\/img\\/amir\\/profile.webp\",\"logo\":\"assets\\/img\\/amir\\/az-monogram-blue.webp\"}','2026-11-09 10:46:57','2026-11-12 11:30:29'),(3,'featured_slugs','[]','2026-11-09 10:46:57','2026-11-14 10:39:51'),(5,'booking','{\"enabled\": true, \"duration\": 30, \"buffer\": 0, \"min_notice\": 120, \"max_days\": 45, \"timezone\": \"Asia/Tehran\", \"slot_interval\": 30, \"owner_notify\": true, \"visitor_notify\": true}','2026-11-10 14:16:47','2026-11-12 10:56:54'),(6,'project-details.13','{\"bundled_slug\":\"novin-aras-books\"}','2026-11-14 10:40:34','2026-11-15 09:17:26'),(7,'project-details.14','{\"bundled_slug\":\"novin-coursescan\",\"cover\":\"\\/assets\\/img\\/novin-coders\\/coursescan\\/cover.webp\",\"gallery\":[\"\\/assets\\/img\\/novin-coders\\/coursescan\\/gallery-01.webp\",\"\\/assets\\/img\\/novin-coders\\/coursescan\\/gallery-02.webp\"],\"source\":\"https:\\/\\/novincoders.ir\\/projects\\/show\\/?slug=coursescan\",\"en\":{\"title\":\"CourseScan\",\"overview\":\"CourseScan brings courses from different platforms into a single Persian discovery interface. The home page starts with search, and the archive lets learners refine results without leaving the catalogue.\",\"features\":[\"Filter courses by topic, instructor, platform, language and price.\",\"Scan course cards for a thumbnail, category, rating and short description.\",\"Browse through a responsive archive with a dedicated filter sidebar.\"],\"approach\":\"The search-first layout uses a light palette, navy text and yellow accents. Astro and Vue components support the front end, and Laravel provides the back end.\"},\"fa\":{\"title\":\"\\u06a9\\u0648\\u0631\\u0633\\u200c\\u0627\\u0633\\u06a9\\u0646 | \\u06a9\\u0634\\u0641 \\u062f\\u0648\\u0631\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0622\\u0645\\u0648\\u0632\\u0634\\u06cc\",\"overview\":\"\\u06a9\\u0648\\u0631\\u0633\\u200c\\u0627\\u0633\\u06a9\\u0646 \\u062f\\u0648\\u0631\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0622\\u0645\\u0648\\u0632\\u0634\\u06cc\\u0650 \\u067e\\u0644\\u062a\\u0641\\u0631\\u0645\\u200c\\u0647\\u0627\\u06cc \\u0645\\u062e\\u062a\\u0644\\u0641 \\u0631\\u0627 \\u062f\\u0631 \\u06cc\\u06a9 \\u0631\\u0627\\u0628\\u0637 \\u0641\\u0627\\u0631\\u0633\\u06cc \\u062c\\u0645\\u0639 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062c\\u0633\\u062a\\u200c\\u0648\\u062c\\u0648 \\u062f\\u0631 \\u0645\\u0631\\u06a9\\u0632 \\u0635\\u0641\\u062d\\u0647\\u0654 \\u0627\\u0635\\u0644\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u06a9\\u0627\\u0631\\u0628\\u0631 \\u062f\\u0631 \\u0622\\u0631\\u0634\\u06cc\\u0648 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0646\\u062a\\u0627\\u06cc\\u062c \\u0631\\u0627 \\u0645\\u0631\\u062d\\u0644\\u0647\\u200c\\u0628\\u0647\\u200c\\u0645\\u0631\\u062d\\u0644\\u0647 \\u062f\\u0642\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u06a9\\u0646\\u062f.\",\"features\":[\"\\u0641\\u06cc\\u0644\\u062a\\u0631 \\u062f\\u0648\\u0631\\u0647\\u200c\\u0647\\u0627 \\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0645\\u0648\\u0636\\u0648\\u0639\\u060c \\u0645\\u062f\\u0631\\u0633\\u060c \\u067e\\u0644\\u062a\\u0641\\u0631\\u0645\\u060c \\u0632\\u0628\\u0627\\u0646 \\u0648 \\u0642\\u06cc\\u0645\\u062a.\",\"\\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0627\\u0631\\u062a\\u200c\\u0647\\u0627\\u06cc \\u062f\\u0648\\u0631\\u0647 \\u0628\\u0627 \\u062a\\u0635\\u0648\\u06cc\\u0631\\u060c \\u062f\\u0633\\u062a\\u0647\\u200c\\u0628\\u0646\\u062f\\u06cc\\u060c \\u0627\\u0645\\u062a\\u06cc\\u0627\\u0632 \\u0648 \\u062a\\u0648\\u0636\\u06cc\\u062d \\u06a9\\u0648\\u062a\\u0627\\u0647.\",\"\\u062c\\u0633\\u062a\\u200c\\u0648\\u062c\\u0648 \\u062f\\u0631 \\u0622\\u0631\\u0634\\u06cc\\u0648 \\u0648\\u0627\\u06a9\\u0646\\u0634\\u200c\\u06af\\u0631\\u0627 \\u0628\\u0627 \\u0646\\u0648\\u0627\\u0631 \\u06a9\\u0646\\u0627\\u0631\\u06cc\\u0650 \\u0641\\u06cc\\u0644\\u062a\\u0631\\u0647\\u0627.\"],\"approach\":\"\\u0637\\u0631\\u0627\\u062d\\u06cc \\u0628\\u0627 \\u0632\\u0645\\u06cc\\u0646\\u0647\\u0654 \\u0631\\u0648\\u0634\\u0646\\u060c \\u0645\\u062a\\u0646 \\u0633\\u0631\\u0645\\u0647\\u200c\\u0627\\u06cc \\u0648 \\u062a\\u0623\\u06a9\\u06cc\\u062f\\u0647\\u0627\\u06cc \\u0632\\u0631\\u062f\\u060c \\u062c\\u0633\\u062a\\u200c\\u0648\\u062c\\u0648 \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0645\\u06cc\\u200c\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0631\\u0627\\u0628\\u0637 \\u0628\\u0627 Astro \\u0648 \\u06a9\\u0627\\u0645\\u067e\\u0648\\u0646\\u0646\\u062a\\u200c\\u0647\\u0627\\u06cc Vue \\u0648 \\u0628\\u06a9\\u200c\\u0627\\u0646\\u062f \\u0628\\u0627 Laravel \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a.\"}}','2026-11-14 10:40:34','2026-11-14 10:40:34'),(8,'project-details.15','{\"bundled_slug\":\"novin-project-m9d3va8ve\"}','2026-11-14 10:40:34','2026-11-15 09:17:21'),(9,'project-details.16','{\"bundled_slug\":\"novin-inova\"}','2026-11-14 10:40:34','2026-11-15 09:17:30'),(10,'project-details.17','{\"bundled_slug\":\"novin-project-wm00gotja\"}','2026-11-14 10:40:34','2026-11-15 09:16:56'),(11,'project-details.18','{\"bundled_slug\":\"novin-myris\"}','2026-11-14 10:40:34','2026-11-15 09:16:50'),(12,'project-details.19','{\"bundled_slug\":\"novin-negin-dam\",\"cover\":\"\\/assets\\/img\\/novin-coders\\/negin-dam\\/cover.webp\",\"gallery\":[\"\\/assets\\/img\\/novin-coders\\/negin-dam\\/gallery-01.webp\",\"\\/assets\\/img\\/novin-coders\\/negin-dam\\/gallery-02.webp\",\"\\/assets\\/img\\/novin-coders\\/negin-dam\\/gallery-03.webp\"],\"source\":\"https:\\/\\/novincoders.ir\\/projects\\/show\\/?slug=negin-dam\",\"en\":{\"title\":\"Negin Dam\",\"overview\":\"Negin Dam gives a dairy farm a Persian website where customers can learn about its products and place a direct order request. The site presents fresh milk and livestock alongside the farm\\u2019s history, values and care practices.\",\"features\":[\"Find information about fresh milk, calves and cows.\",\"Send a direct purchase request through the order form.\",\"Browse hygiene and nutrition practices, the farm timeline and frequently asked questions.\"],\"approach\":\"A responsive RTL layout uses warm neutrals and earth tones to keep product information and the order form easy to find. The project combines Next.js and Tailwind CSS with PHP and Laravel.\"},\"fa\":{\"title\":\"\\u0648\\u0628\\u200c\\u0633\\u0627\\u06cc\\u062a \\u062f\\u0627\\u0645\\u062f\\u0627\\u0631\\u06cc \\u0646\\u06af\\u06cc\\u0646 \\u062f\\u0627\\u0645\",\"overview\":\"\\u0646\\u06af\\u06cc\\u0646 \\u062f\\u0627\\u0645 \\u0648\\u0628\\u200c\\u0633\\u0627\\u06cc\\u062a\\u06cc \\u0641\\u0627\\u0631\\u0633\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0639\\u0631\\u0641\\u06cc \\u0645\\u062d\\u0635\\u0648\\u0644\\u0627\\u062a \\u06cc\\u06a9 \\u062f\\u0627\\u0645\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u062b\\u0628\\u062a \\u0645\\u0633\\u062a\\u0642\\u06cc\\u0645 \\u062f\\u0631\\u062e\\u0648\\u0627\\u0633\\u062a \\u062e\\u0631\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u06a9\\u0646\\u0627\\u0631 \\u0645\\u0639\\u0631\\u0641\\u06cc \\u0634\\u06cc\\u0631 \\u062a\\u0627\\u0632\\u0647 \\u0648 \\u062f\\u0627\\u0645 \\u0632\\u0646\\u062f\\u0647\\u060c \\u062a\\u0627\\u0631\\u06cc\\u062e\\u0686\\u0647\\u0654 \\u0645\\u062c\\u0645\\u0648\\u0639\\u0647\\u060c \\u0627\\u0631\\u0632\\u0634\\u200c\\u0647\\u0627 \\u0648 \\u0634\\u06cc\\u0648\\u0647\\u0654 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062f\\u0627\\u0645 \\u0647\\u0645 \\u062f\\u06cc\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"features\":[\"\\u062f\\u0633\\u062a\\u0631\\u0633\\u06cc \\u0628\\u0647 \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a \\u0634\\u06cc\\u0631 \\u062a\\u0627\\u0632\\u0647\\u060c \\u06af\\u0648\\u0633\\u0627\\u0644\\u0647 \\u0648 \\u06af\\u0627\\u0648 \\u0645\\u0627\\u062f\\u0647.\",\"\\u062b\\u0628\\u062a \\u062f\\u0631\\u062e\\u0648\\u0627\\u0633\\u062a \\u062e\\u0631\\u06cc\\u062f \\u0627\\u0632 \\u0637\\u0631\\u06cc\\u0642 \\u0641\\u0631\\u0645 \\u0633\\u0641\\u0627\\u0631\\u0634 \\u0645\\u0633\\u062a\\u0642\\u06cc\\u0645.\",\"\\u0645\\u0631\\u0648\\u0631 \\u0627\\u0633\\u062a\\u0627\\u0646\\u062f\\u0627\\u0631\\u062f\\u0647\\u0627\\u06cc \\u0628\\u0647\\u062f\\u0627\\u0634\\u062a \\u0648 \\u062a\\u063a\\u0630\\u06cc\\u0647\\u060c \\u0645\\u0633\\u06cc\\u0631 \\u067e\\u06cc\\u0634\\u0631\\u0641\\u062a \\u062f\\u0627\\u0645\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u067e\\u0631\\u0633\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0645\\u062a\\u062f\\u0627\\u0648\\u0644.\"],\"approach\":\"\\u0686\\u06cc\\u062f\\u0645\\u0627\\u0646 \\u0631\\u0627\\u0633\\u062a\\u200c\\u0686\\u06cc\\u0646 \\u0648 \\u0648\\u0627\\u06a9\\u0646\\u0634\\u200c\\u06af\\u0631\\u0627 \\u0628\\u0627 \\u0631\\u0646\\u06af\\u200c\\u0647\\u0627\\u06cc \\u06af\\u0631\\u0645 \\u0648 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0637\\u0631\\u0627\\u062d\\u06cc \\u0634\\u062f\\u0647 \\u062a\\u0627 \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a \\u0645\\u062d\\u0635\\u0648\\u0644 \\u0648 \\u0641\\u0631\\u0645 \\u0633\\u0641\\u0627\\u0631\\u0634 \\u0628\\u0647\\u200c\\u0631\\u0627\\u062d\\u062a\\u06cc \\u067e\\u06cc\\u062f\\u0627 \\u0634\\u0648\\u0646\\u062f. \\u067e\\u0631\\u0648\\u0698\\u0647 Next.js \\u0648 Tailwind CSS \\u0631\\u0627 \\u0628\\u0627 PHP \\u0648 Laravel \\u062a\\u0631\\u06a9\\u06cc\\u0628 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}}','2026-11-14 10:40:34','2026-11-14 10:40:34'),(13,'project-details.20','{\"bundled_slug\":\"novin-saatia-tech\"}','2026-11-14 10:40:34','2026-11-15 09:16:42'),(14,'project-details.21','{\"bundled_slug\":\"novin-vidopad\"}','2026-11-14 10:40:34','2026-11-15 09:16:35'),(15,'project-details.22','{\"bundled_slug\":\"novin-raqet\"}','2026-11-14 10:40:34','2026-11-15 09:16:25'),(16,'project-details.23','{\"bundled_slug\":\"document-studio\",\"cover\":\"\\/assets\\/img\\/amir\\/document-studio\\/cover.webp\",\"gallery\":[\"\\/assets\\/img\\/amir\\/document-studio\\/gallery-01.webp\",\"\\/assets\\/img\\/amir\\/document-studio\\/gallery-02.webp\",\"\\/assets\\/img\\/amir\\/document-studio\\/gallery-03.webp\"],\"source\":null,\"en\":{\"title\":\"Document Studio\",\"overview\":\"Document Studio is a reusable HTML workspace for proposals, reports and other paged documents. The repository separates the editor from the document styles and includes two guides for working with a coding assistant. The gallery shows the editor with the sample proposal included in the repository.\",\"features\":[\"Navigate a multipage document with thumbnail previews, page controls and zoom.\",\"Edit text in place, adjust typography and theme colors, and add or duplicate pages.\",\"Keep drafts in browser storage and export an editable HTML copy.\",\"Review print issues and use the browser print dialog to save an A4 PDF.\"],\"approach\":\"The editor uses plain HTML, CSS and JavaScript with local fonts and browser storage. Print-specific CSS defines the A4 layout. The project runs directly in Chromium browsers without a build step or back end.\"},\"fa\":{\"title\":\"\\u062f\\u0627\\u06a9\\u06cc\\u0648\\u0645\\u0646\\u062a \\u0627\\u0633\\u062a\\u0648\\u062f\\u06cc\\u0648\",\"overview\":\"\\u062f\\u0627\\u06a9\\u06cc\\u0648\\u0645\\u0646\\u062a \\u0627\\u0633\\u062a\\u0648\\u062f\\u06cc\\u0648 \\u06cc\\u06a9 \\u0645\\u062d\\u06cc\\u0637 HTML \\u0642\\u0627\\u0628\\u0644\\u200c\\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647\\u0654 \\u062f\\u0648\\u0628\\u0627\\u0631\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0631\\u0648\\u067e\\u0648\\u0632\\u0627\\u0644\\u060c \\u06af\\u0632\\u0627\\u0631\\u0634 \\u0648 \\u0633\\u0646\\u062f\\u0647\\u0627\\u06cc \\u0686\\u0646\\u062f\\u0635\\u0641\\u062d\\u0647\\u200c\\u0627\\u06cc \\u0627\\u0633\\u062a. \\u06a9\\u062f \\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634\\u06af\\u0631 \\u0627\\u0632 \\u0638\\u0627\\u0647\\u0631 \\u0633\\u0646\\u062f \\u062c\\u062f\\u0627\\u0633\\u062a \\u0648 \\u0631\\u06cc\\u067e\\u0648 \\u062f\\u0648 \\u0631\\u0627\\u0647\\u0646\\u0645\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0631 \\u0628\\u0627 \\u062f\\u0633\\u062a\\u06cc\\u0627\\u0631 \\u06a9\\u062f\\u0646\\u0648\\u06cc\\u0633\\u06cc \\u062f\\u0627\\u0631\\u062f. \\u06af\\u0627\\u0644\\u0631\\u06cc\\u060c \\u062e\\u0648\\u062f \\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634\\u06af\\u0631 \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0631\\u0648\\u067e\\u0648\\u0632\\u0627\\u0644 \\u0646\\u0645\\u0648\\u0646\\u0647\\u0654 \\u062f\\u0627\\u062e\\u0644 \\u0631\\u06cc\\u067e\\u0648 \\u0646\\u0634\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\",\"features\":[\"\\u0645\\u0631\\u0648\\u0631 \\u0633\\u0646\\u062f \\u0686\\u0646\\u062f\\u0635\\u0641\\u062d\\u0647\\u200c\\u0627\\u06cc \\u0628\\u0627 \\u067e\\u06cc\\u0634\\u200c\\u0646\\u0645\\u0627\\u06cc\\u0634 \\u0628\\u0646\\u062f\\u0627\\u0646\\u06af\\u0634\\u062a\\u06cc\\u060c \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0635\\u0641\\u062d\\u0627\\u062a \\u0648 \\u0628\\u0632\\u0631\\u06af\\u200c\\u0646\\u0645\\u0627\\u06cc\\u06cc.\",\"\\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634 \\u0645\\u0633\\u062a\\u0642\\u06cc\\u0645 \\u0645\\u062a\\u0646\\u060c \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u062a\\u0627\\u06cc\\u067e\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0648 \\u0631\\u0646\\u06af\\u200c\\u0647\\u0627 \\u0648 \\u0627\\u0641\\u0632\\u0648\\u062f\\u0646 \\u06cc\\u0627 \\u062a\\u06a9\\u062b\\u06cc\\u0631 \\u0635\\u0641\\u062d\\u0647.\",\"\\u0630\\u062e\\u06cc\\u0631\\u0647\\u0654 \\u067e\\u06cc\\u0634\\u200c\\u0646\\u0648\\u06cc\\u0633 \\u062f\\u0631 \\u0645\\u0631\\u0648\\u0631\\u06af\\u0631 \\u0648 \\u062f\\u0631\\u06cc\\u0627\\u0641\\u062a HTML \\u0642\\u0627\\u0628\\u0644\\u200c\\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634.\",\"\\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u0634\\u06a9\\u0644\\u0627\\u062a \\u0686\\u0627\\u067e \\u0648 \\u0630\\u062e\\u06cc\\u0631\\u0647\\u0654 PDF \\u062f\\u0631 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647\\u0654 A4 \\u0627\\u0632 \\u0637\\u0631\\u06cc\\u0642 \\u0645\\u0631\\u0648\\u0631\\u06af\\u0631.\"],\"approach\":\"\\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634\\u06af\\u0631 \\u0628\\u0627 HTML\\u060c CSS \\u0648 \\u062c\\u0627\\u0648\\u0627\\u0627\\u0633\\u06a9\\u0631\\u06cc\\u067e\\u062a \\u062e\\u0627\\u0645\\u060c \\u0641\\u0648\\u0646\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u062d\\u0644\\u06cc \\u0648 \\u062d\\u0627\\u0641\\u0638\\u0647\\u0654 \\u0645\\u0631\\u0648\\u0631\\u06af\\u0631 \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. CSS \\u0645\\u062e\\u0635\\u0648\\u0635 \\u0686\\u0627\\u067e \\u0686\\u06cc\\u062f\\u0645\\u0627\\u0646 A4 \\u0631\\u0627 \\u062a\\u0639\\u0631\\u06cc\\u0641 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u067e\\u0631\\u0648\\u0698\\u0647 \\u062f\\u0631 \\u0645\\u0631\\u0648\\u0631\\u06af\\u0631\\u0647\\u0627\\u06cc \\u0645\\u0628\\u062a\\u0646\\u06cc \\u0628\\u0631 Chromium \\u0645\\u0633\\u062a\\u0642\\u06cc\\u0645\\u0627\\u064b \\u0648 \\u0628\\u062f\\u0648\\u0646 \\u0645\\u0631\\u062d\\u0644\\u0647\\u0654 \\u0633\\u0627\\u062e\\u062a \\u06cc\\u0627 \\u0628\\u06a9\\u200c\\u0627\\u0646\\u062f \\u0627\\u062c\\u0631\\u0627 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"}}','2026-11-15 09:17:47','2026-11-15 09:17:47'),(17,'project-details.24','{\"bundled_slug\":\"novin-sarva-dental-clinic\",\"cover\":\"\\/assets\\/img\\/novin-coders\\/sarva-dental-clinic\\/cover.webp\",\"gallery\":[\"\\/assets\\/img\\/novin-coders\\/sarva-dental-clinic\\/gallery-01.webp\",\"\\/assets\\/img\\/novin-coders\\/sarva-dental-clinic\\/gallery-02.webp\",\"\\/assets\\/img\\/novin-coders\\/sarva-dental-clinic\\/gallery-03.webp\"],\"source\":null,\"en\":{\"title\":\"Sarva Dental Clinic\",\"overview\":\"For a visitor who already knows which treatment they need, the path starts in the service catalogue. Visitors who need more context can explore treatments and the clinic before heading into online appointments.\",\"features\":[\"Browse treatment pages, including implants, orthodontics and cosmetic dentistry.\",\"Start online appointment booking from the homepage or the services section.\",\"Manage service descriptions, media and appointments from the staff dashboard.\"],\"approach\":\"I built the public site and staff views with PHP and Blade. The responsive RTL interface pairs navy and teal branding with a prominent booking action, while HTML, CSS and JavaScript support the page layouts and interactions.\"},\"fa\":{\"title\":\"\\u06a9\\u0644\\u06cc\\u0646\\u06cc\\u06a9 \\u062f\\u0646\\u062f\\u0627\\u0646\\u067e\\u0632\\u0634\\u06a9\\u06cc \\u0633\\u0631\\u0648\\u0627\",\"overview\":\"\\u0645\\u0631\\u0627\\u062c\\u0639\\u06cc \\u06a9\\u0647 \\u0627\\u0632 \\u0642\\u0628\\u0644 \\u0646\\u0648\\u0639 \\u062f\\u0631\\u0645\\u0627\\u0646\\u0634 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u062f\\u0627\\u0646\\u062f \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0645\\u0633\\u062a\\u0642\\u06cc\\u0645 \\u0633\\u0631\\u0627\\u063a \\u0641\\u0647\\u0631\\u0633\\u062a \\u062e\\u062f\\u0645\\u0627\\u062a \\u0628\\u0631\\u0648\\u062f. \\u06a9\\u0633\\u06cc \\u06a9\\u0647 \\u0647\\u0646\\u0648\\u0632 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0627\\u0633\\u062a \\u0647\\u0645 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647\\u0654 \\u062f\\u0631\\u0645\\u0627\\u0646\\u200c\\u0647\\u0627 \\u0648 \\u06a9\\u0644\\u06cc\\u0646\\u06cc\\u06a9 \\u0628\\u062e\\u0648\\u0627\\u0646\\u062f \\u0648 \\u0628\\u0639\\u062f \\u0648\\u0627\\u0631\\u062f \\u0645\\u0633\\u06cc\\u0631 \\u0646\\u0648\\u0628\\u062a\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0634\\u0648\\u062f.\",\"features\":[\"\\u0645\\u0631\\u0648\\u0631 \\u0635\\u0641\\u062d\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062f\\u0631\\u0645\\u0627\\u0646\\u060c \\u0627\\u0632 \\u0627\\u06cc\\u0645\\u067e\\u0644\\u0646\\u062a \\u0648 \\u0627\\u0631\\u062a\\u0648\\u062f\\u0646\\u0633\\u06cc \\u062a\\u0627 \\u062e\\u062f\\u0645\\u0627\\u062a \\u062a\\u0631\\u0645\\u06cc\\u0645\\u06cc \\u0648 \\u0632\\u06cc\\u0628\\u0627\\u06cc\\u06cc.\",\"\\u0634\\u0631\\u0648\\u0639 \\u0646\\u0648\\u0628\\u062a\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0622\\u0646\\u0644\\u0627\\u06cc\\u0646 \\u0627\\u0632 \\u0635\\u0641\\u062d\\u0647\\u0654 \\u0627\\u0635\\u0644\\u06cc \\u06cc\\u0627 \\u0628\\u062e\\u0634 \\u062e\\u062f\\u0645\\u0627\\u062a.\",\"\\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062a\\u0648\\u0636\\u06cc\\u062d\\u0627\\u062a \\u062e\\u062f\\u0645\\u0627\\u062a\\u060c \\u062a\\u0635\\u0627\\u0648\\u06cc\\u0631 \\u0648 \\u0646\\u0648\\u0628\\u062a\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u067e\\u0646\\u0644 \\u06a9\\u0627\\u0631\\u06a9\\u0646\\u0627\\u0646.\"],\"approach\":\"\\u0633\\u0627\\u06cc\\u062a \\u0639\\u0645\\u0648\\u0645\\u06cc \\u0648 \\u067e\\u0646\\u0644 \\u06a9\\u0627\\u0631\\u06a9\\u0646\\u0627\\u0646 \\u0631\\u0627 \\u0628\\u0627 PHP \\u0648 Blade \\u0633\\u0627\\u062e\\u062a\\u0645. \\u0631\\u0627\\u0628\\u0637 \\u0631\\u0627\\u0633\\u062a\\u200c\\u0686\\u06cc\\u0646 \\u0648 \\u0648\\u0627\\u06a9\\u0646\\u0634\\u200c\\u06af\\u0631\\u0627 \\u0627\\u0632 \\u0633\\u0631\\u0645\\u0647\\u200c\\u0627\\u06cc \\u0648 \\u0641\\u06cc\\u0631\\u0648\\u0632\\u0647\\u200c\\u0627\\u06cc \\u0628\\u0631\\u0646\\u062f \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0645\\u0633\\u06cc\\u0631 \\u0646\\u0648\\u0628\\u062a\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0631\\u0627 \\u062f\\u0631 \\u062f\\u06cc\\u062f \\u0646\\u06af\\u0647 \\u0645\\u06cc\\u200c\\u062f\\u0627\\u0631\\u062f. HTML\\u060c CSS \\u0648 JavaScript \\u0686\\u06cc\\u062f\\u0645\\u0627\\u0646 \\u0648 \\u062a\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0635\\u0641\\u062d\\u0647\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0634\\u06a9\\u0644 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f.\"}}','2026-11-15 09:17:47','2026-11-15 09:17:47'),(18,'project-details.25','{\"bundled_slug\":\"novin-alwin-windows\",\"cover\":\"\\/assets\\/img\\/novin-coders\\/alwin-windows\\/cover.webp\",\"gallery\":[\"\\/assets\\/img\\/novin-coders\\/alwin-windows\\/gallery-01.webp\",\"\\/assets\\/img\\/novin-coders\\/alwin-windows\\/gallery-02.webp\",\"\\/assets\\/img\\/novin-coders\\/alwin-windows\\/gallery-03.webp\",\"\\/assets\\/img\\/novin-coders\\/alwin-windows\\/gallery-04.webp\"],\"source\":null,\"en\":{\"title\":\"Alwin Windows\",\"overview\":\"Alwin gives visitors two ways to decide which window or door fits their project: browsing the catalogue by model, and seeing how the products look in completed installations. The estimator uses their own selections to produce an initial price.\",\"features\":[\"Search and filter window, door and screen models in the product catalogue.\",\"Browse completed installations to see products in context.\",\"Choose a profile material, model and dimensions in the step-by-step estimator.\",\"Manage catalogue items and publication status from the admin panel.\"],\"approach\":\"I used PHP and Blade for the site and the catalogue workspace. HTML and CSS keep the product photography, specifications and blue accents prominent, and JavaScript drives the interactive catalogue and estimator.\"},\"fa\":{\"title\":\"\\u0622\\u0644\\u0648\\u06cc\\u0646 | \\u062f\\u0631 \\u0648 \\u067e\\u0646\\u062c\\u0631\\u0647\\u0654 \\u062f\\u0648\\u062c\\u062f\\u0627\\u0631\\u0647\",\"overview\":\"\\u0622\\u0644\\u0648\\u06cc\\u0646 \\u062f\\u0648 \\u0645\\u0633\\u06cc\\u0631 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u062f\\u0631 \\u0648 \\u067e\\u0646\\u062c\\u0631\\u0647 \\u067e\\u06cc\\u0634 \\u0631\\u0648\\u06cc \\u0628\\u0627\\u0632\\u062f\\u06cc\\u062f\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0645\\u062f\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u062f\\u0631 \\u06a9\\u0627\\u062a\\u0627\\u0644\\u0648\\u06af \\u0645\\u0642\\u0627\\u06cc\\u0633\\u0647 \\u06a9\\u0646\\u062f \\u06cc\\u0627 \\u0645\\u062d\\u0635\\u0648\\u0644 \\u0631\\u0627 \\u062f\\u0631 \\u0646\\u0645\\u0648\\u0646\\u0647\\u200c\\u06a9\\u0627\\u0631\\u0647\\u0627\\u06cc \\u0627\\u062c\\u0631\\u0627\\u0634\\u062f\\u0647 \\u0628\\u0628\\u06cc\\u0646\\u062f. \\u0627\\u0628\\u0632\\u0627\\u0631 \\u0628\\u0631\\u0622\\u0648\\u0631\\u062f \\u0647\\u0645 \\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u062f\\u0634 \\u0642\\u06cc\\u0645\\u062a \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0631\\u0627 \\u0646\\u0634\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\",\"features\":[\"\\u062c\\u0633\\u062a\\u200c\\u0648\\u062c\\u0648 \\u0648 \\u0641\\u06cc\\u0644\\u062a\\u0631 \\u0645\\u062f\\u0644\\u200c\\u0647\\u0627\\u06cc \\u062f\\u0631\\u060c \\u067e\\u0646\\u062c\\u0631\\u0647 \\u0648 \\u062a\\u0648\\u0631\\u06cc \\u062f\\u0631 \\u06a9\\u0627\\u062a\\u0627\\u0644\\u0648\\u06af.\",\"\\u0645\\u0631\\u0648\\u0631 \\u067e\\u0631\\u0648\\u0698\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0627\\u062c\\u0631\\u0627\\u0634\\u062f\\u0647 \\u0648 \\u062f\\u06cc\\u062f\\u0646 \\u0645\\u062d\\u0635\\u0648\\u0644 \\u062f\\u0631 \\u0641\\u0636\\u0627\\u06cc \\u0648\\u0627\\u0642\\u0639\\u06cc.\",\"\\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u062c\\u0646\\u0633 \\u067e\\u0631\\u0648\\u0641\\u06cc\\u0644\\u060c \\u0645\\u062f\\u0644 \\u0648 \\u0627\\u0628\\u0639\\u0627\\u062f \\u062f\\u0631 \\u0627\\u0628\\u0632\\u0627\\u0631 \\u0645\\u0631\\u062d\\u0644\\u0647\\u200c\\u0628\\u0647\\u200c\\u0645\\u0631\\u062d\\u0644\\u0647\\u0654 \\u0628\\u0631\\u0622\\u0648\\u0631\\u062f.\",\"\\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0645\\u062d\\u0635\\u0648\\u0644\\u0627\\u062a \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0627\\u0646\\u062a\\u0634\\u0627\\u0631 \\u0622\\u0646\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u067e\\u0646\\u0644 \\u0627\\u062f\\u0645\\u06cc\\u0646.\"],\"approach\":\"\\u0633\\u0627\\u06cc\\u062a \\u0648 \\u0628\\u062e\\u0634 \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u06a9\\u0627\\u062a\\u0627\\u0644\\u0648\\u06af \\u0631\\u0627 \\u0628\\u0627 PHP \\u0648 Blade \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u06a9\\u0631\\u062f\\u0645. HTML \\u0648 CSS \\u0639\\u06a9\\u0633\\u200c\\u0647\\u0627\\u060c \\u0645\\u0634\\u062e\\u0635\\u0627\\u062a \\u0645\\u062d\\u0635\\u0648\\u0644\\u0627\\u062a \\u0648 \\u0631\\u0646\\u06af \\u0622\\u0628\\u06cc \\u0628\\u0631\\u0646\\u062f \\u0631\\u0627 \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647 \\u0646\\u06af\\u0647 \\u0645\\u06cc\\u200c\\u062f\\u0627\\u0631\\u0646\\u062f \\u0648 JavaScript \\u062a\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u06a9\\u0627\\u062a\\u0627\\u0644\\u0648\\u06af \\u0648 \\u0627\\u0628\\u0632\\u0627\\u0631 \\u0628\\u0631\\u0622\\u0648\\u0631\\u062f \\u0631\\u0627 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}}','2026-11-15 09:17:47','2026-11-15 09:17:47'),(19,'project-details.26','{\"bundled_slug\":\"novin-rb-cafe\",\"cover\":\"\\/assets\\/img\\/novin-coders\\/rb-cafe\\/cover.webp\",\"gallery\":[\"\\/assets\\/img\\/novin-coders\\/rb-cafe\\/gallery-01.webp\",\"\\/assets\\/img\\/novin-coders\\/rb-cafe\\/gallery-02.webp\",\"\\/assets\\/img\\/novin-coders\\/rb-cafe\\/gallery-03.webp\",\"\\/assets\\/img\\/novin-coders\\/rb-cafe\\/gallery-04.webp\"],\"source\":null,\"en\":{\"title\":\"RB Caf\\u00e9 & Restaurant\",\"overview\":\"At the table, guests can scan the menu by category, check prices and see a photo before choosing. The same site offers a separate entrance to the customer club, while staff get views tailored to their roles.\",\"features\":[\"Browse or search photographed menu items by category.\",\"Enter the customer club from the caf\\u00e9 landing page.\",\"Edit menu items and categories in the management panel.\",\"Update item availability from the waiter workspace.\"],\"approach\":\"I used Next.js for the guest and staff interfaces and PHP with Laravel on the back end. Black and yellow tie the homepage, menu and staff workspace together, while each view gives its main action a different place in the layout.\"},\"fa\":{\"title\":\"\\u06a9\\u0627\\u0641\\u0647 \\u0648 \\u0631\\u0633\\u062a\\u0648\\u0631\\u0627\\u0646 \\u0622\\u0631\\u0628\\u06cc\",\"overview\":\"\\u0645\\u0647\\u0645\\u0627\\u0646\\u0650 \\u0633\\u0631 \\u0645\\u06cc\\u0632 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062f\\u0633\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0648 \\u0631\\u0627 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u062f\\u060c \\u0639\\u06a9\\u0633 \\u0648 \\u0642\\u06cc\\u0645\\u062a \\u0647\\u0631 \\u0622\\u06cc\\u062a\\u0645 \\u0631\\u0627 \\u0628\\u0628\\u06cc\\u0646\\u062f \\u0648 \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u06a9\\u0646\\u062f. \\u0647\\u0645\\u06cc\\u0646 \\u0633\\u0627\\u06cc\\u062a \\u0648\\u0631\\u0648\\u062f\\u06cc \\u062c\\u062f\\u0627\\u06af\\u0627\\u0646\\u0647\\u200c\\u0627\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0627\\u0634\\u06af\\u0627\\u0647 \\u0645\\u0634\\u062a\\u0631\\u06cc\\u0627\\u0646 \\u062f\\u0627\\u0631\\u062f \\u0648 \\u0646\\u0645\\u0627\\u06cc \\u06a9\\u0627\\u0631\\u06a9\\u0646\\u0627\\u0646 \\u0647\\u0645 \\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0646\\u0642\\u0634 \\u0622\\u0646\\u200c\\u0647\\u0627 \\u0686\\u06cc\\u062f\\u0647 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"features\":[\"\\u0645\\u0631\\u0648\\u0631 \\u0648 \\u062c\\u0633\\u062a\\u200c\\u0648\\u062c\\u0648\\u06cc \\u0622\\u06cc\\u062a\\u0645\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0648 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u0639\\u06a9\\u0633 \\u0648 \\u062f\\u0633\\u062a\\u0647\\u200c\\u0628\\u0646\\u062f\\u06cc.\",\"\\u0648\\u0631\\u0648\\u062f \\u0628\\u0647 \\u0628\\u0627\\u0634\\u06af\\u0627\\u0647 \\u0645\\u0634\\u062a\\u0631\\u06cc\\u0627\\u0646 \\u0627\\u0632 \\u0644\\u0646\\u062f\\u06cc\\u0646\\u06af \\u06a9\\u0627\\u0641\\u0647.\",\"\\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634 \\u0622\\u06cc\\u062a\\u0645\\u200c\\u0647\\u0627 \\u0648 \\u062f\\u0633\\u062a\\u0647\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u067e\\u0646\\u0644 \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0645\\u0646\\u0648.\",\"\\u0628\\u0647\\u200c\\u0631\\u0648\\u0632\\u0631\\u0633\\u0627\\u0646\\u06cc \\u0645\\u0648\\u062c\\u0648\\u062f\\u06cc \\u0622\\u06cc\\u062a\\u0645\\u200c\\u0647\\u0627 \\u0627\\u0632 \\u067e\\u0646\\u0644 \\u0648\\u06cc\\u062a\\u0631.\"],\"approach\":\"\\u0631\\u0627\\u0628\\u0637 \\u0645\\u0647\\u0645\\u0627\\u0646 \\u0648 \\u06a9\\u0627\\u0631\\u06a9\\u0646\\u0627\\u0646 \\u0631\\u0627 \\u0628\\u0627 Next.js \\u0648 \\u0628\\u06a9\\u200c\\u0627\\u0646\\u062f \\u0631\\u0627 \\u0628\\u0627 PHP \\u0648 Laravel \\u0633\\u0627\\u062e\\u062a\\u0645. \\u0645\\u0634\\u06a9\\u06cc \\u0648 \\u0632\\u0631\\u062f \\u0647\\u0648\\u06cc\\u062a \\u0645\\u0634\\u062a\\u0631\\u06a9 \\u0644\\u0646\\u062f\\u06cc\\u0646\\u06af\\u060c \\u0645\\u0646\\u0648 \\u0648 \\u067e\\u0646\\u0644\\u200c\\u0627\\u0646\\u062f \\u0648 \\u062f\\u0631 \\u0647\\u0631 \\u0646\\u0645\\u0627\\u060c \\u0639\\u0645\\u0644\\u06cc \\u06a9\\u0647 \\u06a9\\u0627\\u0631\\u0628\\u0631 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0628\\u0647 \\u0622\\u0646 \\u0646\\u06cc\\u0627\\u0632 \\u062f\\u0627\\u0631\\u062f \\u062c\\u0627\\u06cc \\u0645\\u0634\\u062e\\u0635\\u06cc \\u062f\\u0627\\u0631\\u062f.\"}}','2026-11-15 09:17:47','2026-11-15 09:17:47'),(20,'project-details.27','{\"bundled_slug\":\"novin-fitnet\",\"cover\":\"\\/assets\\/img\\/novin-coders\\/fitnet\\/cover.webp\",\"gallery\":[\"\\/assets\\/img\\/novin-coders\\/fitnet\\/gallery-01.webp\",\"\\/assets\\/img\\/novin-coders\\/fitnet\\/gallery-02.webp\",\"\\/assets\\/img\\/novin-coders\\/fitnet\\/gallery-03.webp\",\"\\/assets\\/img\\/novin-coders\\/fitnet\\/gallery-04.webp\"],\"source\":null,\"en\":{\"title\":\"Fitnet\",\"overview\":\"Fitnet makes it possible to fit a workout around the rest of the day. Users can find a nearby gym, check what it offers, see the credits a visit needs and pick an available entry window before reviewing the booking.\",\"features\":[\"Search or filter gyms and compare facilities, locations and starting credit costs.\",\"Open a gym profile to review services and select an available time slot.\",\"See credit balance and upcoming bookings from the PWA dashboard.\",\"Learn how the credit and booking flow works from the public landing page.\"],\"approach\":\"I built a mobile-first PWA with Next.js and a PHP and Laravel back end. The public landing introduces the service, and the app keeps gym discovery, time selection and the booking review together.\"},\"fa\":{\"title\":\"\\u0641\\u06cc\\u062a\\u200c\\u0646\\u062a | \\u06a9\\u0634\\u0641 \\u0648 \\u0631\\u0632\\u0631\\u0648 \\u0628\\u0627\\u0634\\u06af\\u0627\\u0647\",\"overview\":\"\\u0641\\u06cc\\u062a\\u200c\\u0646\\u062a \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u06a9\\u0627\\u0631\\u0628\\u0631 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u0631\\u0627 \\u062f\\u0631 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u0654 \\u0631\\u0648\\u0632\\u0634 \\u062c\\u0627 \\u0628\\u062f\\u0647\\u062f. \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0634\\u06af\\u0627\\u0647 \\u0646\\u0632\\u062f\\u06cc\\u06a9\\u0634 \\u0631\\u0627 \\u067e\\u06cc\\u062f\\u0627 \\u06a9\\u0646\\u062f\\u060c \\u0627\\u0645\\u06a9\\u0627\\u0646\\u0627\\u062a \\u0648 \\u0627\\u0639\\u062a\\u0628\\u0627\\u0631 \\u0644\\u0627\\u0632\\u0645 \\u0631\\u0627 \\u0628\\u0628\\u06cc\\u0646\\u062f\\u060c \\u06cc\\u06a9 \\u0628\\u0627\\u0632\\u0647\\u0654 \\u0648\\u0631\\u0648\\u062f \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u06a9\\u0646\\u062f \\u0648 \\u0642\\u0628\\u0644 \\u0627\\u0632 \\u062b\\u0628\\u062a\\u060c \\u0631\\u0632\\u0631\\u0648 \\u0631\\u0627 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u062f.\",\"features\":[\"\\u062c\\u0633\\u062a\\u200c\\u0648\\u062c\\u0648 \\u0648 \\u0641\\u06cc\\u0644\\u062a\\u0631 \\u0628\\u0627\\u0634\\u06af\\u0627\\u0647\\u200c\\u0647\\u0627 \\u0648 \\u0645\\u0642\\u0627\\u06cc\\u0633\\u0647\\u0654 \\u0627\\u0645\\u06a9\\u0627\\u0646\\u0627\\u062a\\u060c \\u0645\\u0648\\u0642\\u0639\\u06cc\\u062a \\u0648 \\u0627\\u0639\\u062a\\u0628\\u0627\\u0631 \\u0644\\u0627\\u0632\\u0645.\",\"\\u0645\\u0631\\u0648\\u0631 \\u062e\\u062f\\u0645\\u0627\\u062a \\u0647\\u0631 \\u0628\\u0627\\u0634\\u06af\\u0627\\u0647 \\u0648 \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u0633\\u0627\\u0646\\u0633 \\u0645\\u0648\\u062c\\u0648\\u062f \\u0627\\u0632 \\u0635\\u0641\\u062d\\u0647\\u0654 \\u062c\\u0632\\u0626\\u06cc\\u0627\\u062a.\",\"\\u062f\\u06cc\\u062f\\u0646 \\u0645\\u0648\\u062c\\u0648\\u062f\\u06cc \\u0627\\u0639\\u062a\\u0628\\u0627\\u0631 \\u0648 \\u0631\\u0632\\u0631\\u0648 \\u0628\\u0639\\u062f\\u06cc \\u062f\\u0631 \\u062f\\u0627\\u0634\\u0628\\u0648\\u0631\\u062f \\u0648\\u0628\\u200c\\u0627\\u067e.\",\"\\u0622\\u0634\\u0646\\u0627\\u06cc\\u06cc \\u0628\\u0627 \\u0645\\u0631\\u0627\\u062d\\u0644 \\u0627\\u0639\\u062a\\u0628\\u0627\\u0631 \\u0648 \\u0631\\u0632\\u0631\\u0648 \\u0627\\u0632 \\u0637\\u0631\\u06cc\\u0642 \\u0644\\u0646\\u062f\\u06cc\\u0646\\u06af \\u0639\\u0645\\u0648\\u0645\\u06cc.\"],\"approach\":\"\\u0648\\u0628\\u200c\\u0627\\u067e \\u067e\\u06cc\\u0634\\u200c\\u0631\\u0648\\u0646\\u062f\\u0647 \\u0631\\u0627 \\u0628\\u0627 \\u0631\\u0648\\u06cc\\u06a9\\u0631\\u062f \\u0645\\u0648\\u0628\\u0627\\u06cc\\u0644\\u200c\\u0645\\u062d\\u0648\\u06